INSERT [dbo].[CustomerReview] ([CustomerReviewID], [SubjectRowID], [SubjectID], [ReviewText], [Rating], [StatusID], [CreatedByUserID], [LastModifiedByUserID], [CreatedDateTime], [LastModifiedDateTime]) VALUES (2, 1, 2, N'The second step is to include each element of the first (left) collection in the result set even if that element has no matches in the right collection. This is accomplished by calling DefaultIfEmpty on each sequence of matching elements from the group join. In this example, DefaultIfEmpty is called on each sequence of matching Pet objects. The method returns a collection that contains a single, default value if the sequence of matching Pet objects is empty for any Person object, thereby ensuring that each Person object is represented in the result collection.', 4, 1, 1, 1, CAST(N'2021-03-21T05:20:25.390' AS DateTime), CAST(N'2021-03-21T05:20:25.390' AS DateTime))
