	,@New_StatusID as bigint
	,@New_CartTotal as float
	,@New_TaxTotal as float
	,@New_DiscountTotal as float
	,@SpProfileID as bigint
	,@CartID as bigint OUTPUT
AS
BEGIN
	INSERT INTO [CartOrder] 
		(
		 [BuyerProfileID]
		,[ParentCartID]
		,[OrderStatusID]
		,[StatusID]

		,[DeliveryAddressID] -- null
		,[DeliveryAddress] -- null
		,[OrderSupplierId] -- null
		,[SupplierDeliveryOptionPairID] -- null

		,[OrderTotal]
		,[TaxTotal]
		,[DiscountTotal] 

		,[DeliveryTotal] -- 0
		,[PaymentTotal] -- 0
		,[CalculatedPayout] -- 0
		,[ActualPayout] -- 0
		,[CalculatedPayIn] -- 0
		,[ActualPayIn] -- 0


		,[CreatedDateTime]
		,[CreatedByUserID]
		,[LastModifiedDateTime]
		,[LastModifiedByUserID]
		)
	VALUES
		(
		  @New_BuyerProfileID
		, null --[ParentCartID] 
		, @New_CartStatusID
		, @New_StatusID
		, null -- [DeliveryAddressID]
		, null -- [DeliveryAddress]
		, null -- [OrderSupplierId]
		, null -- [SupplierDeliveryOptionPairID]
		, @New_CartTotal
		, @New_TaxTotal
		, @New_DiscountTotal
		, 0 					--[DeliveryTotal]
		, 0						--[PaymentTotal] 
		, 0						--[CalculatedPayout]
		, 0						--[ActualPayout]
		, 0						--[CalculatedPayIn] 
		, 0						--[ActualPayIn] 

		, GETDATE()
		, @SpProfileID
		, GETDATE()
		, @SpProfileID
		)

	SET @CartID = SCOPE_IDENTITY();
