CREATE PROCEDURE [dbo].[CustomerReview_AutoUpdateStatus] 
AS
BEGIN
DECLARE @rowCounter INT;

	UPDATE [CustomerReview]
	SET
		 StatusID=4,
		 LastModifiedDateTime = GETDATE()
	WHERE 
		 StatusID=1
		 AND 
		 LastModifiedDateTime < GETDATE()-90

SET @rowCounter =  @@RowCount

RETURN @rowCounter

END

