/****** Object:  StoredProcedure [dbo].[Order_AutoUpdateStatus]    Script Date: 5/5/2021 9:27:07 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Order_AutoUpdateStatus] 
AS
BEGIN
DECLARE @rowCounter INT;

	UPDATE [CartOrder] 
	SET
		 [OrderStatusID]=10,
		 LastModifiedDateTime = GETDATE()
	WHERE 
		 OrderNumber is not null
		  and OrderStatusID=8
		  and LastModifiedDateTime < GETDATE()-2

SET @rowCounter =  @@RowCount

	UPDATE [CartOrder] 
	SET
		 [OrderStatusID]=13,
		 LastModifiedDateTime = GETDATE()
	WHERE 
		OrderNumber is not null
		  and (OrderStatusID=11 or OrderStatusID=12 )
		  and StatusID <> 4
		  and LastModifiedDateTime < GETDATE()-90

SET @rowCounter = @rowCounter + @@ROWCOUNT;


	UPDATE [CartOrder] 
	SET
		 [StatusID]=4,
		 LastModifiedDateTime = GETDATE()
	WHERE 
		OrderNumber is not null
		  and (OrderStatusID=1 or OrderStatusID=3)
		  and StatusID <> 4
		  and LastModifiedDateTime < GETDATE()-90

SET @rowCounter = @rowCounter + @@ROWCOUNT;

RETURN @rowCounter

END

