CREATE PROCEDURE [dbo].[Order_Insert] 
	 @New_BuyerProfileID as bigint
	,@New_ParentCartID as bigint
	,@New_OrderStatusID as bigint
	,@New_StatusID as bigint
	,@New_DeliveryAddressID as bigint
	,@New_DeliveryAddress as varchar(max)
	,@New_OrderSupplierId as bigint
	,@New_SupplierDeliveryOptionPairID  as bigint

	,@New_OrderTotal as float
	,@New_TaxTotal as float
	,@New_DeliveryTotal as float
	,@New_DiscountTotal as float
	,@New_PaymentTotal as float

	,@SpProfileID as bigint
	,@OrderID as bigint OUTPUT
AS
BEGIN
	INSERT INTO [CartOrder] 
		(
		 [BuyerProfileID]
		,[ParentCartID]
		,[OrderStatusID]
		,[StatusID]

		,[DeliveryAddressID]
		,[DeliveryAddress] 
		,[OrderSupplierId]
		,[SupplierDeliveryOptionPairID] 

		,[OrderTotal]
		,[TaxTotal]
		,[DeliveryTotal] 
		,[DiscountTotal]
		,[PaymentTotal] 

		,[CalculatedPayout] -- 0
		,[ActualPayout] -- 0
		,[CalculatedPayIn] -- 0
		,[ActualPayIn] -- 0


		,[CreatedDateTime]
		,[CreatedByUserID]
		,[LastModifiedDateTime]
		,[LastModifiedByUserID]
		)
	VALUES
		(
		  @New_BuyerProfileID
		, @New_ParentCartID
		, @New_OrderStatusID
		, @New_StatusID
		, @New_DeliveryAddressID 
		, @New_DeliveryAddress
		, @New_OrderSupplierId 
		, @New_SupplierDeliveryOptionPairID
		, @New_OrderTotal
		, @New_TaxTotal
		, @New_DeliveryTotal
		, @New_DiscountTotal
		, @New_PaymentTotal 

		, 0						--[CalculatedPayout]
		, 0						--[ActualPayout]
		, 0						--[CalculatedPayIn] 
		, 0						--[ActualPayIn] 

		, GETDATE()
		, @SpProfileID
		, GETDATE()
		, @SpProfileID
		)

	SET @OrderID = SCOPE_IDENTITY();
	RETURN @@RowCount
END

