CREATE PROCEDURE [dbo].[UpdateTableStatus] 
	 @TableName as varchar(50)
    ,@StatusID as int   
AS
BEGIN
	DECLARE @query as varchar(max)
	
	SET @query = '
	UPDATE ' + @TableName + '
	SET 
	[StatusID] = @StatusID'

	EXEC @query
	
	RETURN @@RowCount	
